const paketAnzahl = items.length;

const buchAnzahl = items.reduce((sum, item) => {
  return sum + Number(item.json.Menge || 0);
}, 0);

// Globale Workflow-Variable
const globalData = $getWorkflowStaticData('global');
globalData.anzahlUmgewandeltePakete = paketAnzahl;
globalData.anzahlUmgewandelteBuecher = buchAnzahl;

return items.map(item => {
  const row = item.json;

  /*
   * Versanddatum: ISO-Datum in YYYYMMDD umwandeln
   * Beispiel: 2026-05-05T13:56:27.160Z -> 20260505
   */
  row.Versanddatum = String(row.Versanddatum ?? '')
    .slice(0, 10)
    .replace(/-/g, '');

  /*
   * Menge: Länge 7 inkl. Pluszeichen
   * Beispiel: 3 -> +000003
   */
  row.Menge = '+' + String(Number(row.Menge)).padStart(6, '0');

  /*
   * VKPreis: 2 Nachkommastellen, Punkt entfernen, auf 9 Stellen auffüllen
   * Beispiel: 12.99 -> 000001299
   */
  row.VKPreis = Number(row.VKPreis)
    .toFixed(2)
    .replace('.', '')
    .padStart(9, '0');

  /*
   * PLZ: falls führende Null fehlt, ergänzen
   * Danach auf die ersten 3 Stellen kürzen
   */
  row.PLZ = String(row.PLZ ?? '');

  if (row.PLZ.length < 5) {
    row.PLZ = '0' + row.PLZ;
  }

  row.PLZ = row.PLZ.slice(0, 3);

  /*
   * EAN: Leerzeichen entfernen
   */
  row.EAN = String(row.EAN ?? '').replace(/\s+/g, '');

  return item;
});

const staticData = $getWorkflowStaticData('global');

staticData.titel = 'BB | MediaControl AT vom '+ $now.setZone('Europe/Berlin').minus({ days: 1 }).toFormat('yyyy-MM-dd');
staticData.sendto = 'jesse.balsam@buecherbuechse.de,christoph@buecherbuechse.de, lisa@buecherbuechse.de,helen.hilpert@buecherbuechse.de';

return [
  {
    json: {
      success: true,
    },
  },
];

const staticData = $getWorkflowStaticData('global');
const titel = staticData.titel || 'Kein Titel gesetzt';
const sendto = staticData.sendto || '';
const anzahlUmgewandeltePakete =
  staticData.anzahlUmgewandeltePakete || 0;
const anzahlUmgewandelteBuecher =
  staticData.anzahlUmgewandelteBuecher || 0;
const escapeHtml = (value) => {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};
// Tabellen-Items aus Payload Anpassung holen (= ein Merge-Input)
const datenItems = $('Payload Anpassung').all();
const titelMap = new Map();
for (const item of datenItems) {
  const row = item.json;
  const titelKey = String(row.Titel ?? '').trim();
  const ean = String(row.EAN ?? '').trim();
  const menge = Number(row.Menge || 0);
  // VKPreis aus MediaControl-Format (z.B. "000001299") zurück in Euro (12.99)
  const vkPreis = Number(String(row.VKPreis ?? '0').replace(/\D/g, '')) / 100;
  if (!titelMap.has(titelKey)) {
    titelMap.set(titelKey, {
      Titel: titelKey,
      EAN: ean,
      Menge: 0,
      VKPreis: vkPreis,
    });
  }
  titelMap.get(titelKey).Menge += menge;
}
const aggregierteTitel = Array.from(titelMap.values())
  .sort((a, b) => b.Menge - a.Menge);
const tabellenZeilen = aggregierteTitel.map(row => {
  return `
    <tr>
      <td>${escapeHtml(row.Titel)}</td>
      <td>${escapeHtml(row.EAN)}</td>
      <td align="right">${escapeHtml(row.Menge)}</td>
      <td align="right">${escapeHtml(row.VKPreis.toFixed(2))} &euro;</td>
    </tr>
  `;
}).join('');
const mailText = `
<p>Der FTP Upload vom ${escapeHtml(titel)} - Flow war erfolgreich!</p>
<p>
  Insgesamt wurden ${escapeHtml(anzahlUmgewandeltePakete)} Pakete aus der DB-Abfrage zum FTP Upload durchgegeben.<br>
  Diese Pakete enthalten insgesamt ${escapeHtml(anzahlUmgewandelteBuecher)} Bücher.
</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse: collapse; font-family: Arial, sans-serif; font-size: 14px;">
  <thead>
    <tr>
      <th align="left">Titel</th>
      <th align="left">EAN</th>
      <th align="right">Menge</th>
      <th align="right">VK-Preis (brutto)</th>
    </tr>
  </thead>
  <tbody>
    ${tabellenZeilen}
  </tbody>
</table>
<p>
  Liebe Grüße<br>
  ${escapeHtml(titel)} - Flow
</p>
`;
return [
  {
    json: {
      success: true,
      titel,
      sendto,
      anzahlUmgewandeltePakete,
      anzahlUmgewandelteBuecher,
      anzahlTitel: aggregierteTitel.length,
      mailText,
    },
    // CSV-Datei aus dem FTP-Success-Input (Convert to File1) weitergeben
    binary: items.find(item => item.binary)?.binary,
  },
];

const staticData = $getWorkflowStaticData('global');

const titel = staticData.titel || 'Kein Titel gesetzt';
const sendto = staticData.sendto || '';

return items.map(item => {
  return {
    json: {
      ...item.json,

      titel,
      sendto,

      mailText: `Der FTP Upload vom ${titel} - Flow schlug fehl!

Liebe Grüße 
Der ${titel} - Flow `,
    },
  };
});

